"""Türkçe — siyer (sira_001 … sira_150)."""

T = {
"sira_001": ("Peygamber Muhammed ﷺ hangi şehirde doğdu?", ["Mekke", "Medine", "Taif", "Kudüs"], "Peygamber Muhammed ﷺ Hicaz'da, Mekke'de doğdu."),
"sira_002": ("Fil olayıyla anılan, Peygamber ﷺ'in doğduğu yıla ne denir?", ["Fil Yılı", "Zafer Yılı", "Deve Yılı", "Nur Yılı"], "Allah'ın Kâbe'yi koruduğu Fil olayı, Fil suresinde anlatılır."),
"sira_003": ("Peygamber ﷺ'in ilk eşinin adı neydi?", ["Hatice", "Aişe", "Hafsa", "Zeynep"], "Hatice bint Huveylid, Peygamber ﷺ'in ilk eşi ve mesajına ilk inanan kişiydi."),
"sira_004": ("Peygamber ﷺ ilk vahyi hangi mağarada aldı?", ["Hira mağarası", "Sevr mağarası", "Ashab-ı Kehf mağarası", "Uhud mağarası"], "İlk vahiy, Mekke yakınındaki Nur dağındaki Hira mağarasında geldi."),
"sira_005": ("Vahyi Peygamber ﷺ'e hangi melek getirdi?", ["Cebrail", "Mikail", "İsrafil", "Malik"], "Kur'an, Cebrail'in vahyi Allah'ın izniyle indirdiğini açıkça belirtir."),
"sira_006": ("Peygamber ﷺ ve ashabının Mekke'den Medine'ye göçüne ne denir?", ["Hicret", "İsra", "Miraç", "Fetih"], "Hicret, İslam takviminin başlangıcı olan Medine'ye tarihi göçtür."),
"sira_007": ("Peygamber ﷺ ile Ebu Bekir hangi şehre hicret ettiler?", ["Medine", "Taif", "Şam", "Kudüs"], "Peygamber ﷺ ile Ebu Bekir Mekke'den Medine'ye (o zamanki adıyla Yesrib) hicret ettiler."),
"sira_008": ("Kur'an, hicret sırasında bir sahabiyi «ikinin ikincisi, mağaradayken» diye tanımlar. Kimdir?", ["Ebu Bekir", "Ömer", "Osman", "Ali"], "Kur'an, hicret sırasında Sevr mağarasında Peygamber ﷺ'e eşlik eden Ebu Bekir'i kasteder."),
"sira_009": ("Kur'an'da anılan hangi savaşta küçük bir Müslüman ordusu çok daha büyük bir kuvveti yendi?", ["Bedir Savaşı", "Uhud Savaşı", "Hendek Savaşı", "Huneyn Savaşı"], "Bedir'de Allah küçük bir mümin topluluğuna çok daha büyük bir orduya karşı zafer verdi."),
"sira_010": ("Peygamber ﷺ ve ashabının Mekke'ye büyük ölçüde barışçıl dönüşüne ne denir?", ["Mekke'nin Fethi", "Mekke Savaşı", "Mekke Kuşatması", "Mekke'nin Düşüşü"], "Mekke'nin fethi büyük ölçüde barışçıl gerçekleşti, yaygın bir kan dökülmedi."),
"sira_011": ("Peygamber ﷺ'in hayatının sonuna doğru verdiği son hutbeye ne denir?", ["Veda Hutbesi", "Mekke Hutbesi", "Mağara Hutbesi", "Bedir Hutbesi"], "Veda Hutbesi, Peygamber ﷺ'in son haccı sırasında verildi."),
"sira_012": ("Kur'an, vahyinin hangi ayda başladığını bildirir?", ["Ramazan", "Muharrem", "Recep", "Zilhicce"], "Kur'an, Ramazan'ın Kur'an'ın indirildiği ay olduğunu bildirir."),
"sira_013": ("Peygamber ﷺ'in vahiy almadan önceki mesleği neydi?", ["Tüccar", "Yalnızca çoban", "Demirci", "Kâtip"], "Peygamber ﷺ ticaretle uğraştı; bu, hayatının iyi bilinen bir gerçeğidir."),
"sira_014": ("Annesinin ölümünden sonra Peygamber ﷺ'e hangi dedesi baktı?", ["Abdülmuttalib", "Ebu Talib", "Ebu Leheb", "Ebu Süfyan"], "Abdülmuttalib, annesi Âmine'nin ölümünden sonra genç Muhammed ﷺ'e baktı."),
"sira_015": ("Dedesinin ölümünden sonra Peygamber ﷺ'i hangi amcası büyüttü?", ["Ebu Talib", "Abbas", "Hamza", "Ebu Leheb"], "Ebu Talib, Abdülmuttalib'in ölümünden sonra yeğenini büyütmeyi üstlendi."),
"sira_016": ("Kur'an'da anılan, Peygamber ﷺ'in Mekke'den Kudüs'e gece yolculuğuna ne denir?", ["İsra", "Hicret", "Fetih", "Gazve"], "İsra suresi bu mucizevi gece yolculuğunu anlatarak başlar."),
"sira_017": ("Peygamber ﷺ'in kızlarından hangisi Ali bin Ebu Talib ile evlendi?", ["Fatıma", "Zeynep", "Rukiye", "Ümmü Gülsüm"], "Peygamber ﷺ ile Hatice'nin kızı Fatıma, Ali bin Ebu Talib ile evlendi; bu yaygın olarak bilinen bir gerçektir."),
"sira_018": ("Hicrete atıfla İslam takvim yılının başlangıcı hangi aydır?", ["Muharrem", "Ramazan", "Şevval", "Zilkade"], "İslam takvimi, hicret yılını esas alarak Muharrem ayıyla başlar."),
"sira_019": ("Peygamber ﷺ'in ezan okumak için seçtiği İslam'ın ilk müezzini kimdi?", ["Bilal bin Rebah", "Ebu Bekir", "Ömer bin Hattab", "Selman-ı Farisi"], "Güzel sesiyle Bilal, İslam'ın ilk müezzini olarak seçildi."),
"sira_020": ("Peygamber ﷺ Medine yakınına vardığında kurduğu ilk mescit hangisiydi?", ["Kuba Mescidi", "Mescid-i Haram", "Mescid-i Aksa", "Kıbleteyn Mescidi"], "Medine'nin kapısı Kuba'ya varan Peygamber ﷺ orada ilk mescidi kurdu."),
"sira_021": ("Peygamber ﷺ'in annesinin adı neydi?", ["Âmine", "Hatice", "Halime", "Fatıma"], "Âmine bint Vehb, Peygamber ﷺ'in annesiydi; Halime ise sütannesiydi."),
"sira_022": ("Doğumundan önce vefat eden Peygamber ﷺ'in babasının adı neydi?", ["Abdullah", "Ebu Talib", "Abdülmuttalib", "Hamza"], "Abdülmuttalib'in oğlu Abdullah, oğlu Muhammed ﷺ doğmadan önce vefat etti."),
"sira_023": ("Mekkeliler vahiyden önce dürüstlüğü nedeniyle Peygamber ﷺ'e hangi lakabı verdi?", ["El-Emin (güvenilir)", "El-Faruk", "Es-Sıddık", "Seyfullah"], "Vahiyden önce bile ona el-Emin deniyordu: insanlar mallarını ona emanet ederdi."),
"sira_024": ("Mekke'nin fethi hicretin hangi yılında gerçekleşti?", ["8. yıl", "2. yıl", "5. yıl", "10. yıl"], "Hicri 8. yılda Peygamber ﷺ Mekke'ye neredeyse savaşsız girdi ve halkını bağışladı."),
"sira_025": ("Peygamber ﷺ Veda Haccı'nı hicretin hangi yılında yaptı?", ["10. yıl", "6. yıl", "8. yıl", "12. yıl"], "Veda Haccı hicri 10. yılda yapıldı; Peygamber ﷺ son hutbesini orada verdi."),
"sira_026": ("Peygamber ﷺ'in kaç kızı vardı?", ["4", "1", "2", "7"], "Zeynep, Rukiye, Ümmü Gülsüm ve Fatıma: Peygamber ﷺ'in dört kızı."),
"sira_027": ("Hicret eden Müslümanları karşılayıp yardım eden Medinelilere ne denir?", ["Ensar (yardımcılar)", "Muhacirler", "Kureyş", "Tâbiîn"], "Ensar, «yardımcılar», evlerini ve mallarını muhacir kardeşleriyle paylaştı."),
"sira_028": ("Medine'ye göç etmek için Mekke'yi terk eden Müslümanlara ne denir?", ["Muhacirler (göç edenler)", "Ensar", "Hanifler", "Gaziler"], "Muhacirler, imanlarını korumak için Mekke'deki evlerini ve mallarını bıraktılar."),
"sira_029": ("Bedir Savaşı hangi ayda gerçekleşti?", ["Ramazan", "Muharrem", "Zilhicce", "Recep"], "Bedir Savaşı hicri 2. yılın Ramazan ayında gerçekleşti."),
"sira_030": ("Kıble Kâbe'ye çevrilmeden önce Müslümanlar hangi şehre doğru namaz kılıyordu?", ["Kudüs (Beytülmakdis)", "Medine", "Taif", "Şam"], "Müslümanlar önce Beytülmakdis'e doğru namaz kıldı; sonra Allah Mescid-i Haram'a yönelmeyi emretti (Kur'an 2:142-144)."),
"sira_031": ("Peygamber Muhammed ﷺ hangi kabileye mensuptu?", ["Kureyş", "Evs", "Hazrec", "Sakif"], "Bütün bir sure kabilesinin adını taşır: Kureyş."),
"sira_032": ("Peygamber ﷺ Kureyş'in hangi kolundandı?", ["Haşimoğulları", "Ümeyyeoğulları", "Mahzumoğulları", "Temimoğulları"], "Peygamber ﷺ, büyük dedesi Haşim'in kolu Haşimoğullarındandı."),
"sira_033": ("Peygamber ﷺ'i çölde emziren sütannenin adı neydi?", ["Halime es-Sa'diyye", "Âmine", "Hatice", "Fatıma"], "Mekke geleneğine göre bebek bedevi bir sütanneye verildi: Halime es-Sa'diyye."),
"sira_034": ("Bedir kahramanı olan Peygamber ﷺ'in hangi amcası Uhud'da şehit düştü?", ["Hamza", "Ebu Talib", "Abbas", "Ebu Leheb"], "Hamza bin Abdülmuttalib Bedir'de savaştı ve Uhud Savaşı'nda şehit oldu."),
"sira_035": ("Peygamber ﷺ'in evinde büyüyen hangi amcaoğlu dördüncü halife oldu?", ["Ali bin Ebu Talib", "Cafer", "Akil", "Abbas"], "Ebu Talib'in oğlu Ali, Peygamber ﷺ ile büyüdü ve dördüncü raşit halife oldu."),
"sira_036": ("Peygamber ﷺ'in vefatından sonra ilk halife kim oldu?", ["Ebu Bekir", "Ömer", "Osman", "Ali"], "Ebu Bekir es-Sıddık ilk halife olarak seçildi."),
"sira_037": ("Ebu Bekir, Peygamber ﷺ'e tereddütsüz inandığı için hangi lakabı taşır?", ["Es-Sıddık (doğrulayan)", "El-Faruk", "Zünnureyn", "Seyfullah"], "Ebu Bekir'e hakkı tasdik eden ve ona inanan anlamında es-Sıddık denir."),
"sira_038": ("Ömer bin Hattab hangi lakabı taşır?", ["El-Faruk (hakkı batıldan ayıran)", "Es-Sıddık", "Zünnureyn", "El-Emin"], "Ömer'e hakkı batıldan ayıran anlamında el-Faruk denir."),
"sira_039": ("Osman bin Affan'a neden «Zünnureyn», iki nur sahibi denir?", ["Peygamber ﷺ'in iki kızıyla art arda evlendi", "İki lamba taşıdı", "Kur'an'ı iki kez ezberledi", "İki kez hicret etti"], "Osman, Rukiye ile ve onun vefatından sonra Ümmü Gülsüm ile evlendi; ikisi de Peygamber ﷺ'in kızlarıydı."),
"sira_040": ("Dört raşit halife hangi sırayla birbirini izledi?", ["Ebu Bekir, Ömer, Osman, Ali", "Ali, Ömer, Ebu Bekir, Osman", "Ömer, Ebu Bekir, Ali, Osman", "Ebu Bekir, Ali, Ömer, Osman"], "Ebu Bekir, sonra Ömer, sonra Osman, sonra Ali."),
"sira_041": ("Peygamber ﷺ'in mesajına ilk inanan kişi kimdi?", ["Eşi Hatice", "Ebu Bekir", "Ali", "Bilal"], "Hatice ilk vahiyden itibaren ona inandı ve onu destekledi."),
"sira_042": ("Bilal'i efendisinin işkencesinden kurtarmak için kim satın aldı?", ["Ebu Bekir", "Ömer", "Hamza", "Osman"], "Ebu Bekir Bilal'i satın alıp azat etti."),
"sira_043": ("Mekke'de imanı uğruna öldürülen İslam'ın ilk şehidi kimdi?", ["Ammar'ın annesi Sümeyye", "Esma", "Ümmü Seleme", "Safiye"], "Ammar bin Yasir'in annesi Sümeyye bint Hayyat, Ebu Cehil tarafından öldürüldü."),
"sira_044": ("Mekke'de zulüm gören Müslümanların ilk hicreti hangi ülkeye oldu?", ["Habeşistan (Etiyopya)", "İran", "Yemen", "Mısır"], "İlk muhacirler adil bir kralın yanına, Habeşistan'a gittiler."),
"sira_045": ("Müslümanları koruyan ve Peygamber ﷺ'in gıyabında cenaze namazını kıldığı Habeşistan kralına ne denirdi?", ["Necaşi", "Herakleios", "Kisra", "Mukavkıs"], "Peygamber ﷺ Necaşi'nin ölümünü aynı gün haber verdi ve ashabıyla onun için namaz kıldı."),
"sira_046": ("Hangi sahabi Necaşi'nin huzurunda İslam'ı anlattı?", ["Cafer bin Ebu Talib", "Osman", "Bilal", "Mus'ab bin Umeyr"], "Cafer krala Peygamber ﷺ'in öğrettiklerini anlattı ve ona Meryem suresinden ayetler okudu."),
"sira_047": ("Peygamber ﷺ'in hangi amcası Kur'an'da adıyla kınanır?", ["Ebu Leheb", "Ebu Talib", "Abbas", "Hamza"], "«Ebu Leheb'in elleri kurusun, kendisi de kurudu!»"),
"sira_048": ("Peygamber ﷺ'in eşi Hatice'yi ve amcası Ebu Talib'i kaybettiği yıla ne denir?", ["Hüzün Yılı", "Fil Yılı", "Heyetler Yılı", "Kıtlık Yılı"], "Peygamber ﷺ'in iki büyük destekçisi aynı yıl vefat etti; bu yıl Hüzün Yılı olarak bilinir."),
"sira_049": ("Peygamber ﷺ İslam'a davet ettikten sonra hangi şehirden kovulup yaralandı ve dağlar meleğinin halkı ezmesini reddetti?", ["Taif", "Medine", "Hayber", "Tebük"], "Taif'te reddedilince, torunlarının Allah'a ibadet etmesi umuduyla halkını helak etmeyi reddetti."),
"sira_050": ("İsra ve Miraç sırasında Müslümanlara hangi ibadet farz kılındı?", ["Beş vakit namaz", "Ramazan orucu", "Zekât", "Hac"], "O gece namaz farz kılındı; elliden beşe indirildi, sevabı elli olarak kaldı."),
"sira_051": ("Necm suresine göre Peygamber ﷺ Miraç'ta en uç sınırdaki hangi ağacı gördü?", ["Sidretü'l-Münteha", "Mübarek zeytin ağacı", "Meryem'in hurma ağacı", "Tuba ağacı"], "«Sidretü'l-Münteha'nın yanında», en uç sınırdaki sedir ağacı."),
"sira_052": ("Yesribliler'in hicretten önce Peygamber ﷺ'e verdikleri biatlara ne denir?", ["Akabe biatları", "Hudeybiye antlaşması", "Ağaç altı biatı", "Medine Sözleşmesi"], "Yesribliler hicretten önce Mina yakınındaki Akabe'de Peygamber ﷺ'e biat ettiler."),
"sira_053": ("Peygamber ﷺ hicretten önce İslam'ı öğretmesi için hangi sahabiyi Yesrib'e gönderdi?", ["Mus'ab bin Umeyr", "Bilal", "Ebu Hüreyre", "Halid bin Velid"], "Mus'ab bin Umeyr Yesrib'e gönderilen ilk elçiydi; yeni Müslümanlara Kur'an öğretti."),
"sira_054": ("Peygamber ﷺ'in hicret için yola çıktığı gece yatağında kim yattı?", ["Ali bin Ebu Talib", "Ebu Bekir", "Zeyd bin Harise", "Bilal"], "Ali, gözcüleri yanıltmak için yatağına yattı, sonra emanetleri Mekkelilere iade etti."),
"sira_055": ("Peygamber ﷺ ile Ebu Bekir hicret sırasında hangi mağarada saklandılar?", ["Sevr mağarası", "Hira mağarası", "Uhud mağarası", "Taif mağarası"], "Mekke'nin güneyindeki Sevr mağarasında üç gün saklandılar."),
"sira_056": ("Ebu Bekir'in hangi kızı mağaraya erzak taşıdı ve «iki kuşaklı» lakabını aldı?", ["Esma", "Aişe", "Ümmü Gülsüm", "Ümmü Ruman"], "Esma erzakı bağlamak için kuşağını ikiye yırttı: bu yüzden «Zâtü'n-Nitâkayn»."),
"sira_057": ("Hicret sırasında Peygamber ﷺ'i takip eden Süraka'ya ne oldu?", ["Atı toprağa gömüldü ve eman diledi", "Peygamber ﷺ'e yetişti", "Çölde kayboldu", "Hastalandı"], "Atının ayakları toprağa gömüldü; Süraka eman diledi ve zarar vermeden ayrıldı."),
"sira_058": ("Kur'an'da geçen Medine'nin eski adı neydi?", ["Yesrib", "Taybe", "Hayber", "Bekke"], "Kur'an, müttefikler savaşını hatırlatarak «Ey Yesrib halkı…» der."),
"sira_059": ("Hudeybiye'de çöken Peygamber ﷺ'in devesinin adı neydi?", ["Kasvâ", "Burak", "Düldül", "Adbâ"], "Hudeybiye'de Kasvâ çöktü; Peygamber ﷺ dedi ki: «Fili alıkoyan onu da alıkoydu.»"),
"sira_060": ("Peygamber ﷺ Medine'ye varınca Muhacirler ile Ensar arasında ne kurdu?", ["İkişer ikişer kardeşlik", "Bir vergi", "Bir ordu", "Bir pazar"], "Muhacirlerle Ensar'ı kardeş ilan etti; her muhacire Ensar'dan bir kardeş."),
"sira_061": ("Peygamber ﷺ'in Medine toplulukları arasındaki ilişkileri düzenlediği belgeye ne denir?", ["Medine Sözleşmesi (Sahife)", "Hudeybiye antlaşması", "Taif antlaşması", "Kuba beratı"], "Sahife, Müslümanların ve Medine'deki diğer kabilelerin hak ve yükümlülüklerini belirledi."),
"sira_062": ("Peygamber ﷺ'in mescidinde yaşayan yoksul sahabilere ne denirdi?", ["Ehl-i Suffe (sofa ehli)", "Muhacirler", "Ensar", "Havariler"], "Ebu Hüreyre, Peygamber ﷺ'in doyurduğu Suffe ehlinden olduğunu anlatır."),
"sira_063": ("Bedir Savaşı hicretten kaç yıl sonra gerçekleşti?", ["İki", "Beş", "Sekiz", "On"], "Bedir, hicri 2. yılda Ramazan'da yapıldı."),
"sira_064": ("Allah, Bedir'de müminlere destek olarak kaç melek göndermeyi vaat etti?", ["Bin", "Yüz", "On", "Yüz bin"], "«Sizi peş peşe gelen bin melekle destekleyeceğim.»"),
"sira_065": ("Uhud'da okçuların hangi hatası savaşın seyrini değiştirdi?", ["Peygamber ﷺ'in emrine rağmen tepeyi terk ettiler", "Çok erken ok attılar", "Uyuyakaldılar", "Taraf değiştirdiler"], "Peygamber ﷺ okçulara yerlerinden ayrılmamalarını emretmişti; çoğu ganimet için indi ve düşman süvarisi arkadan dolandı."),
"sira_066": ("Uhud dağı hangi şehrin yakınındadır?", ["Medine", "Mekke", "Taif", "Kudüs"], "Uhud dağı Medine'nin kuzeyindedir; savaş eteğinde yapıldı."),
"sira_067": ("Medine'yi müttefiklere karşı savunmak için hendek kazmayı hangi sahabi önerdi?", ["Selman-ı Farisi", "Bilal", "Ebu Zer", "Suheyb"], "Selman-ı Farisi, İran'da bilinen bir taktik olan hendeği önerdi."),
"sira_068": ("Hendek Savaşı, onu anlatan sureye göre başka hangi adla bilinir?", ["Ahzab (Müttefikler) Savaşı", "Bedir Savaşı", "Huneyn Savaşı", "Mute Savaşı"], "Ahzab suresi, Medine'yi kuşatan müttefik orduları ve onlara karşı gönderilen rüzgârı hatırlatır."),
"sira_069": ("Hudeybiye'de bir ağacın altında yapılan, Allah'ın razı olduğunu bildirdiği biata ne denir?", ["Bey'atü'r-Rıdvan", "Akabe biatı", "Kadınlar biatı", "Fetih biatı"], "«Ağacın altında sana biat ederken Allah müminlerden razı oldu.»"),
"sira_070": ("Hudeybiye antlaşmasından sonra inen, «Sana apaçık bir fetih verdik» diye başlayan sure hangisidir?", ["Fetih", "Nasr", "Enfal", "Tevbe"], "«Şüphesiz sana apaçık bir fetih verdik»: Fetih suresi."),
"sira_071": ("Hudeybiye antlaşması hicretin hangi yılında yapıldı?", ["6. yıl", "2. yıl", "8. yıl", "10. yıl"], "Hudeybiye antlaşması hicri 6. yılda Müslümanlarla Kureyş arasında yapıldı."),
"sira_072": ("Peygamber ﷺ'in İslam'a davet mektubunu alan ve Ebu Süfyan'ı onun hakkında sorgulayan Bizans imparatoru kimdi?", ["Herakleios", "Neron", "Konstantin", "Justinianus"], "Herakleios mektubu aldıktan sonra Ebu Süfyan'ı Peygamber ﷺ hakkında sorguladı."),
"sira_073": ("Peygamber ﷺ Hayber'de «Yarın sancağı Allah'ın ve Resulünün sevdiği bir adama vereceğim» dedikten sonra sancağı kime verdi?", ["Ali bin Ebu Talib", "Ebu Bekir", "Ömer", "Sa'd bin Ebu Vakkas"], "Gözleri ağrıyan Ali'yi çağırdı; tükürüğünü sürüp onu iyileştirdi ve sancağı ona verdi."),
"sira_074": ("Mute Savaşı'nda hangi üç komutan art arda şehit düştü?", ["Zeyd bin Harise, Cafer bin Ebu Talib ve Abdullah bin Revaha", "Hamza, Mus'ab ve Sa'd", "Ebu Bekir, Ömer ve Osman", "Bilal, Selman ve Suheyb"], "Peygamber ﷺ Medine'de duyurdu: «Zeyd sancağı aldı ve şehit oldu, sonra Cafer, sonra İbn Revaha… sonra Allah'ın kılıçlarından biri aldı.»"),
"sira_075": ("Peygamber ﷺ hangi sahabiye «Allah'ın kılıçlarından bir kılıç» dedi?", ["Halid bin Velid", "Ali", "Hamza", "Ebu Ubeyde"], "Mute'de «Allah'ın kılıçlarından bir kılıç» olan Halid bin Velid sancağı aldı ve orduyu kurtardı."),
"sira_076": ("Mekke'nin fethinde Peygamber ﷺ Kâbe'nin etrafındaki putlara ne yaptı?", ["«Hak geldi, batıl yok oldu» diyerek devirdi", "Sattı", "Medine'ye götürdü", "Yerinde bıraktı"], "Putlara asasıyla vurup «Hak geldi, batıl yok oldu» dedi."),
"sira_077": ("Mekke'nin fethedildiği gün Kâbe'nin üstünden ezanı kim okudu?", ["Bilal", "Ebu Bekir", "Ali", "Ömer"], "Peygamber ﷺ Bilal'e Kâbe'nin üstüne çıkıp ezan okumasını emretti."),
"sira_078": ("Fetih günü Peygamber ﷺ kendisine zulmetmiş yenik Mekkelilere ne dedi?", ["«Gidin, serbestsiniz»", "«Yarın yargılanacaksınız»", "«Şehri terk edin»", "«Fidye ödeyin»"], "Onları bağışladı: «Gidin, serbestsiniz.»"),
"sira_079": ("Kur'an'da adı geçen hangi savaşta Müslümanlar kalabalıklarına rağmen başta gafil avlandı?", ["Huneyn", "Bedir", "Uhud", "Hayber"], "«Huneyn gününde çokluğunuz sizi böbürlendirmişti ama size hiçbir fayda vermedi.»"),
"sira_080": ("Tebük seferine katılmayan hangi sahabi dürüstçe itiraf etti ve bir vahiyle bağışlandı?", ["Ka'b bin Malik", "Ebu Zer", "Enes bin Malik", "Ebu Hüreyre"], "Ka'b bin Malik doğruyu söyledi, elli gün dışlanmaya katlandı, sonra Allah bağışlandığını vahyetti (9:118)."),
"sira_081": ("Birçok kabilenin İslam'ı kabul etmek için Medine'ye geldiği hicri 9. yıla ne denir?", ["Heyetler Yılı", "Hüzün Yılı", "Fil Yılı", "Kuraklık Yılı"], "Mekke'nin fethinden sonra Arap kabilelerinin heyetleri Medine'ye akın etti."),
"sira_082": ("Peygamber ﷺ Veda Hutbesi'ni nerede verdi?", ["Arafat'ta", "Medine'de", "Uhud dağında", "Taif'te"], "Veda Hutbesi, Veda Haccı sırasında Arafat'ta verildi."),
"sira_083": ("Veda Haccı'nda inen hangi ayet dinin tamamlandığını bildirir?", ["«Bugün sizin için dininizi kemale erdirdim»", "«Yaratan Rabbinin adıyla oku»", "«Allah'ın yardımı gelince»", "«De ki: O Allah birdir»"], "«Bugün sizin için dininizi kemale erdirdim ve üzerinizdeki nimetimi tamamladım.»"),
"sira_084": ("Peygamber ﷺ hangi şehirde vefat etti ve defnedildi?", ["Medine", "Mekke", "Kudüs", "Taif"], "Hicri 11. yılda Medine'de vefat etti ve orada defnedildi."),
"sira_085": ("Peygamber ﷺ hangi eşinin odasına defnedildi?", ["Aişe'nin", "Hatice'nin", "Hafsa'nın", "Ümmü Seleme'nin"], "Vefat ettiği yere, bugün Mescid-i Nebevi'nin içinde kalan Aişe'nin odasına defnedildi."),
"sira_086": ("Peygamber ﷺ'in vefatında «Kim Muhammed'e tapıyorsa bilsin ki Muhammed öldü; kim Allah'a tapıyorsa Allah diridir» diyen kimdi?", ["Ebu Bekir", "Ömer", "Ali", "Bilal"], "Ebu Bekir sahabeyi teskin etti ve «Muhammed yalnızca bir elçidir…» (3:144) ayetini okudu."),
"sira_087": ("Fatıma ile Ali'nin oğulları olan Peygamber ﷺ'in iki torununun adı neydi?", ["Hasan ve Hüseyin", "İbrahim ve İsmail", "Zeyd ve Üsame", "Cafer ve Akil"], "Peygamber ﷺ'in çok sevdiği Hasan ve Hüseyin."),
"sira_088": ("Peygamber ﷺ'in hangi eşi Ebu Bekir'in kızıydı?", ["Aişe", "Hafsa", "Zeynep", "Sevde"], "Ebu Bekir'in kızı Aişe çok sayıda hadis rivayet etti."),
"sira_089": ("Peygamber ﷺ'in hangi eşi Ömer bin Hattab'ın kızıydı?", ["Hafsa", "Aişe", "Ümmü Habibe", "Meymune"], "Hafsa bint Ömer; Kur'an'ın ilk derlenmiş nüshası onda saklandı."),
"sira_090": ("Peygamber ﷺ'den en çok hadis rivayet eden sahabi kimdir?", ["Ebu Hüreyre", "Enes bin Malik", "Abdullah bin Ömer", "Cabir"], "Peygamber ﷺ'in yanından ayrılmayan Ebu Hüreyre, en çok hadis rivayet eden sahabidir."),
"sira_091": ("Hangi genç sahabi on yıl boyunca tek bir azar işitmeden Peygamber ﷺ'e hizmet etti?", ["Enes bin Malik", "Üsame bin Zeyd", "İbn Abbas", "Zeyd bin Sabit"], "Enes dedi ki: «Peygamber ﷺ'e on yıl hizmet ettim; bana bir kez bile ‘öf’ demedi, ‘bunu neden yaptın’ demedi.»"),
"sira_092": ("Peygamber ﷺ hangi genç amcaoğlu için «Allah'ım, ona Kitab'ı öğret» diye dua etti?", ["Abdullah bin Abbas", "Ali", "Cafer", "Üsame"], "Peygamber ﷺ İbn Abbas'ı bağrına bastı ve «Allah'ım, ona Kitab'ı öğret» dedi."),
"sira_093": ("Peygamber ﷺ hangi sahabiyi önce Allah'ın birliğine davet etmesini söyleyerek Yemen'e gönderdi?", ["Muaz bin Cebel", "Bilal", "Yalnız Ebu Musa", "Zeyd bin Harise"], "«Ehl-i kitap bir topluluğa gidiyorsun: onları önce Allah'tan başka ilah olmadığına şahitlik etmeye çağır…»"),
"sira_094": ("Peygamber ﷺ hangi sahabiye «bu ümmetin emini» dedi?", ["Ebu Ubeyde bin Cerrah", "Ebu Bekir", "Osman", "Halid"], "«Her ümmetin bir emini vardır; bu ümmetin emini Ebu Ubeyde bin Cerrah'tır.»"),
"sira_095": ("Vahiy kâtibi olan hangi sahabiyi Ebu Bekir Kur'an'ı toplamakla görevlendirdi?", ["Zeyd bin Sabit", "Ebu Hüreyre", "Enes bin Malik", "Selman"], "Yemame savaşından sonra Ebu Bekir, Zeyd bin Sabit'i Kur'an'ı toplamakla görevlendirdi."),
"sira_096": ("Kur'an'ın resmi nüshaları hangi halife döneminde vilayetlere gönderildi?", ["Osman bin Affan", "Ebu Bekir", "Ömer", "Ali"], "Osman mushafı çoğalttırdı ve her vilayete bir nüsha gönderdi."),
"sira_097": ("«El-Farisi» denilen sahabi Selman hangi ülkeden geldi?", ["İran", "Habeşistan", "Bizans", "Yemen"], "Selman-ı Farisi, «İranlı», hakikati aramak için İran'dan geldi."),
"sira_098": ("Bizans topraklarından gelen hangi sahabiye «er-Rumi» denir?", ["Suheyb", "Bilal", "Selman", "Ebu Zer"], "Suheyb er-Rumi, Mekke'de Müslüman olmadan önce Bizanslılar arasında büyüdü."),
"sira_099": ("Peygamber ﷺ'in Medine'deki mescidine ne denir?", ["Mescid-i Nebevi", "Mescid-i Haram", "Mescid-i Aksa", "Kuba Mescidi"], "Medine'de kurduğu mescide Peygamber Mescidi, Mescid-i Nebevi denir."),
"sira_100": ("«Muhammed» ismi Kur'an'da kaç kez geçer?", ["Dört", "Bir", "On iki", "Yüz"], "3:144, 33:40, 47:2 ve 48:29 ayetlerinde; «Ahmed» ismi ise 61:6'da geçer."),
"sira_101": ("Kur'an 33:21 ayetinde Peygamber ﷺ'i müminler için nasıl niteler?", ["Güzel bir örnek", "Sert bir yargıç", "Bir kral", "Bir şair"], "«Andolsun, Allah'ın Resulünde sizin için güzel bir örnek vardır.»"),
"sira_102": ("Peygamber ﷺ'in künyesi neydi?", ["Ebü'l-Kasım", "Ebu Bekir", "Ebu Abdullah", "Ebu Talib"], "En büyük oğlu Kasım'dan dolayı ona Ebü'l-Kasım denirdi."),
"sira_103": ("Peygamber ﷺ'in Medine'de doğan ve küçükken vefat eden oğlunun adı neydi?", ["İbrahim", "Kasım", "Abdullah", "Hasan"], "Medine'de doğan İbrahim bebekken vefat etti; Peygamber ﷺ ağladı ve kalbin Allah'ı hoşnutsuz edecek söz söylemeden hüzünlendiğini söyledi."),
"sira_104": ("Peygamber ﷺ vahiyden önce kimin adına Şam'a ticaret kervanı götürdü?", ["Hatice", "Ebu Bekir", "Ebu Süfyan", "Abbas"], "Zengin bir tüccar olan Hatice, Şam kervanını ona emanet etti ve sonra evlilik teklif etti."),
"sira_105": ("Genç Muhammed ﷺ, Hacerülesved'in yerine konması konusundaki kabile anlaşmazlığını nasıl çözdü?", ["Onu her kabilenin tuttuğu bir örtüye koydu, sonra kendi eliyle yerleştirdi", "Tek başına taşıdı", "Kura çekti", "Ebu Bekir'e emanet etti"], "Bir örtü serdi, taşı üzerine koydu, kabile reislerine örtüyü birlikte kaldırttı ve kendi eliyle yerine koydu."),
"sira_106": ("Peygamber ﷺ ilk vahyi kaç yaşında aldı?", ["Kırk", "Yirmi beş", "Elli", "Altmış"], "Vahiy, kırk yaşındayken Hira mağarasında başladı."),
"sira_107": ("Peygamber ﷺ ilk vahiyden sonra Hatice'nin kitapları bilen hangi amcaoğluna götürüldü?", ["Varaka bin Nevfel", "Ebu Talib", "Ebu Leheb", "Velid"], "Varaka dedi ki: «Bu, Allah'ın Musa'ya gönderdiği Nâmûs'tur (melek).»"),
"sira_108": ("«Yakın akrabanı uyar» ayetinden sonra Peygamber ﷺ Kureyş'e açıkça seslenmek için hangi tepeye çıktı?", ["Safa", "Uhud", "Arafat", "Hira"], "Safa tepesine çıktı, Kureyş kabilelerini çağırdı ve onları şiddetli bir azaba karşı uyardı."),
"sira_109": ("Hicret yılını başlangıç alan Müslüman takvimini hangi halife başlattı?", ["Ömer bin Hattab", "Ebu Bekir", "Osman", "Ali"], "Ömer döneminde hicret, takvimin başlangıcı olarak seçildi."),
"sira_110": ("Peygamber ﷺ hicretten sonra Medine'de kaç yıl yaşadı?", ["On", "Üç", "Yirmi", "On üç"], "Hicretten hicri 11. yıldaki vefatına kadar Medine'de on yıl yaşadı."),
"sira_111": ("Peygamber ﷺ hicretten önce Mekke'de kaç yıl tebliğ etti?", ["On üç", "Üç", "On", "Yirmi üç"], "Mekke'de on üç, sonra Medine'de on yıl: yirmi üç yıllık görev."),
"sira_112": ("Peygamber ﷺ'i şiirleriyle savunan ve kendisi için Cebrail'in desteğini istediği şair sahabi kimdi?", ["Hassan bin Sabit", "Ka'b bin Malik", "Abdullah bin Revaha", "Lebid"], "Peygamber ﷺ Hassan'a dedi ki: «Onlara cevap ver, Cebrail seninledir.»"),
"sira_113": ("Peygamber ﷺ hangi sahabinin güzel kıraati için ona «Davud ailesinin mizmarlarından biri» verildiğini söyledi?", ["Ebu Musa el-Eş'ari", "Bilal", "Übey bin Ka'b", "İbn Mesud"], "Onun okuyuşunu duyunca Peygamber ﷺ, Ebu Musa'ya Davud ailesinin mizmarlarından birinin verildiğini söyledi."),
"sira_114": ("Peygamber ﷺ Kur'an'ı dört sahabiden öğrenmeyi tavsiye etti. Şunlardan hangisi onlardan biriydi?", ["Abdullah bin Mesud", "Ebu Hüreyre", "Enes bin Malik", "Halid bin Velid"], "«Kur'an'ı dört kişiden öğrenin: İbn Mesud, Salim, Muaz bin Cebel ve Übey bin Ka'b.»"),
"sira_115": ("Peygamber ﷺ hangi savaşta yüzünden yaralandı ve bir dişini kaybetti?", ["Uhud", "Bedir", "Huneyn", "Hayber"], "Uhud'da dişi kırıldı ve yüzü yaralandı."),
"sira_116": ("Peygamber ﷺ Uhud'daki okçu hangi sahabiye «At! Anam babam sana feda olsun» dedi?", ["Sa'd bin Ebu Vakkas", "Talha", "Zübeyr", "Ali"], "Peygamber ﷺ ona oklar uzatarak «At, anam babam sana feda olsun» dedi."),
"sira_117": ("Müslümanlar Bedir Savaşı'na yol açan hangi kervanı yakalamak için yola çıktılar?", ["Şam'dan dönen Ebu Süfyan'ın kervanını", "Necaşi'nin kervanını", "İranlıların kervanını", "Taif'in kervanını"], "Ebu Süfyan'ın yönettiği Kureyş kervanı kaçtı ama Mekke ordusu Bedir'e geldi."),
"sira_118": ("Mekke reisi Ebu Süfyan ne zaman Müslüman oldu?", ["Mekke'nin fethinde", "Hicretten önce", "Bedir'de", "Peygamber ﷺ'in vefatından sonra"], "Ebu Süfyan, Peygamber ﷺ'in Mekke'ye girişinin arifesinde Müslüman oldu."),
"sira_119": ("Mekke vadisinde Hacer ve oğlu İsmail için hangi kaynak fışkırdı?", ["Zemzem", "Nil", "Fırat", "Şeria"], "Bir melek yere vurdu ve Zemzem suyu fışkırdı; Hacer etrafına bir havuz yaptı."),
"sira_120": ("Peygamber ﷺ'in yüzüğünde ne yazılıydı?", ["«Muhammed Resulullah»", "«Allahu Ekber»", "«La ilahe illallah»", "Yalnızca adı"], "Gümüş yüzüğünde üç satır halinde «Muhammed, Allah'ın Resulü» yazılıydı."),
"sira_121": ("Aişe'ye göre Peygamber ﷺ hangi yiyecekleri severdi?", ["Tatlı ve bal", "Balık", "Keskin baharatlar", "Yalnızca sirke"], "Aişe, Peygamber ﷺ'in tatlıyı ve balı sevdiğini anlatır."),
"sira_122": ("Peygamber ﷺ haftanın hangi günü doğdu ve o gün oruç da tutardı?", ["Pazartesi", "Cuma", "Cumartesi", "Çarşamba"], "Pazartesi orucu sorulunca dedi ki: «O gün doğdum ve o gün bana vahiy geldi.»"),
"sira_123": ("«Nübüvvet mührü» Peygamber ﷺ'in bedeninin neresindeydi?", ["İki omzunun arasında", "Elinde", "Alnında", "Göğsünde"], "Nübüvvet mührü iki omzunun arasındaydı."),
"sira_124": ("Bir marangoz Peygamber ﷺ'in minberini hangi ağaçtan yaptı?", ["Ilgın ağacından", "Sedirden", "Zeytinden", "Hurmadan"], "Peygamber ﷺ, insanlara hitap ettiği ılgın ağacından bir minber yaptırdı."),
"sira_125": ("Medine'nin hangi iki büyük kabilesi Ensar'ı oluşturdu?", ["Evs ve Hazrec", "Kureyş ve Sakif", "Temim ve Hevazin", "Kinde ve Hemdan"], "Uzun süre rakip olan Evs ve Hazrec, İslam'da birleşip Ensar oldular."),
"sira_126": ("Kur'an Peygamber ﷺ'in eşlerine hangi unvanı verir?", ["Müminlerin Anneleri", "Medine kraliçeleri", "Kureyş'in kızları", "Kitab'ın koruyucuları"], "«Eşleri onların anneleridir»: Müminlerin Anneleri."),
"sira_127": ("Hicret, Hristiyan takvimine göre hangi yılda gerçekleşti?", ["622", "570", "632", "610"], "622'deki hicret, Müslüman takviminin başlangıcıdır."),
"sira_128": ("Ensar'dan kardeşi malının yarısını teklif edince Abdurrahman bin Avf ne cevap verdi?", ["«Bana pazarı göster»", "Hepsini kabul etti", "Bir ev istedi", "Konuşmayı reddetti"], "Dedi ki: «Allah malını ve aileni mübarek kılsın; bana yalnızca pazarı göster», ve ticaretle zenginleşti."),
"sira_129": ("Peygamber ﷺ hangi sahabiye Kur'an'ın en büyük ayetinin hangisi olduğunu sordu ve cevabı (Âyetü'l-Kürsî) için onu tebrik etti?", ["Übey bin Ka'b", "Ebu Bekir", "Zeyd bin Sabit", "Bilal"], "Übey «Allah, O'ndan başka ilah yoktur, Hayy'dır…» diye cevap verdi; Peygamber ﷺ «İlim sana kutlu olsun ey Ebü'l-Münzir!» dedi."),
"sira_130": ("Peygamber ﷺ'in Medine'deki mescidinin yeri nasıl seçildi?", ["Devesinin çöktüğü yer", "Kura ile", "Pazarın ortası", "Uhud dağı"], "Devesini serbest bıraktı: çöktüğü yere mescit yapıldı."),
"sira_131": ("Peygamber ﷺ'in hepsi küçük yaşta vefat eden kaç oğlu vardı?", ["Üç", "Bir", "Beş", "Hiç"], "Hatice'den Kasım ve Abdullah, Medine'de doğan İbrahim."),
"sira_132": ("Peygamber ﷺ'in azat edip oğlu gibi büyüttüğü hangi sahabi Üsame'nin babasıydı?", ["Zeyd bin Harise", "Bilal", "Selman", "Ammar"], "Peygamber ﷺ'in sevgilisi Zeyd bin Harise, Üsame bin Zeyd'in babasıydı."),
"sira_133": ("Peygamber ﷺ vefatından kısa süre önce gençliğine rağmen hangi genç sahabiyi ordu komutanı yaptı?", ["Üsame bin Zeyd", "Enes bin Malik", "İbn Abbas", "İbn Ömer"], "Peygamber ﷺ komutayı Üsame'ye verdi ve yaşını eleştirenlere babası gibi buna layık olduğunu söyledi."),
"sira_134": ("Peygamber ﷺ'in hangi dedesi uzun süredir kapalı olan Zemzem kuyusunu yeniden kazdı?", ["Abdülmuttalib", "Haşim", "Abdümenaf", "Kusay"], "Abdülmuttalib Zemzem'i yeniden kazdı ve hacılar için onunla ilgilendi."),
"sira_135": ("Bedir Savaşı'nda Peygamber ﷺ'in yanında yaklaşık kaç kişi vardı?", ["Üç yüzü biraz aşkın", "On bin", "Bin", "Elli"], "Bedir'deki Müslümanlar çok daha büyük bir orduya karşı üç yüzü biraz aşkındı."),
"sira_136": ("Peygamber ﷺ Müslüman takviminin hangi ayında doğdu?", ["Rebiülevvel", "Ramazan", "Muharrem", "Zilhicce"], "Fil Yılı'nda Rebiülevvel ayında doğdu."),
"sira_137": ("Peygamber ﷺ hicret sırasında Medine'ye hangi ayda vardı?", ["Rebiülevvel", "Ramazan", "Muharrem", "Recep"], "Kuba'da konakladıktan sonra Rebiülevvel'de Medine'ye vardı."),
"sira_138": ("Kureyş, Peygamber ﷺ'i koruyan Haşimoğullarını tecrit etmek için hangi anlaşmayı yaptı?", ["Boykot: onlarla ticaret ve evlilik yok", "On yıllık ateşkes", "Kâbe'nin paylaşımı", "Askeri ittifak"], "Kureyş bir boykot anlaşması imzaladı ve Haşimoğulları yıllarca bir vadide kuşatıldı."),
"sira_139": ("Peygamber ﷺ açık davetten önce Mekke'deki görevine nasıl başladı?", ["Yakın çevresini gizlice davet ederek", "Bir orduyla", "Krallara mektupla", "Bir hacla"], "Davet açığa çıkmadan önce akrabalarını ve dostlarını gizlice davet etti."),
"sira_140": ("Hacer, İsmail için su ararken hangi iki tepe arasında koştu?", ["Safa ve Merve", "Uhud ve Sevr", "Arafat ve Mina", "Hira ve Sevr"], "Safa ile Merve arasında yedi kez koştu: hacıların sa'yinin kökeni."),
"sira_141": ("Peygamber ﷺ hangi torunu için «Bu oğlum bir seyyiddir; Allah onun vasıtasıyla iki Müslüman topluluğu barıştıracak» dedi?", ["Hasan", "Hüseyin", "Üsame", "İbn Abbas"], "Hasan bin Ali, Peygamber ﷺ'in haber verdiği gibi sonradan iki büyük Müslüman topluluğu barıştırdı."),
"sira_142": ("Hasan ve Hüseyin'in annesi olan Peygamber ﷺ'in kızının adı neydi?", ["Fatıma", "Zeynep", "Rukiye", "Ümmü Gülsüm"], "Ali'nin eşi Fatıma, Hasan ve Hüseyin'in annesiydi."),
"sira_143": ("Peygamber ﷺ'in en büyük kızı kimdi?", ["Zeynep", "Fatıma", "Rukiye", "Ümmü Gülsüm"], "Zeynep, Peygamber ﷺ'in dört kızının en büyüğüydü."),
"sira_144": ("Habeş asıllı eski köle olan hangi sahabi güzel sesi için müezzin seçildi?", ["Bilal bin Rebah", "Selman", "Suheyb", "Zeyd"], "Ebu Bekir'in azat ettiği Bilal, Peygamber ﷺ'in müezzini oldu."),
"sira_145": ("Peygamber ﷺ hangi sahabi için «İnsanlardan bir dost (halil) edinseydim o olurdu» dedi?", ["Ebu Bekir", "Ömer", "Ali", "Osman"], "«Ümmetimden bir dost edinseydim Ebu Bekir'i edinirdim, fakat o benim kardeşim ve arkadaşımdır.»"),
"sira_146": ("Mekke ile birlikte hangi şehre «Haremeyn», iki harem denir?", ["Medine", "Kudüs", "Taif", "Şam"], "Mekke ve Medine iki kutsal şehirdir: Haremeyn."),
"sira_147": ("Peygamber ﷺ hicretten sonra kaç kez hac yaptı?", ["Bir kez, Veda Haccı", "Üç kez", "Her yıl", "Hiç"], "Hicretten sonra yalnızca bir hac yaptı: hicri 10. yıldaki Veda Haccı."),
"sira_148": ("Enes'e göre bir bedevi mal isteyerek cübbesini sertçe çekince Peygamber ﷺ ne yaptı?", ["Gülümsedi ve ona bir şey verilmesini emretti", "Onu cezalandırttı", "Tek söz etmeden gitti", "Onu kovdu"], "Peygamber ﷺ ona döndü, güldü ve ona bir şey verilmesini emretti."),
"sira_149": ("Mescid-i Aksa'nın bulunduğu hangi şehir İsra yolculuğunun varış noktasıydı?", ["Kudüs", "Şam", "Kahire", "Bağdat"], "İsra yolculuğu Peygamber ﷺ'i Mekke'den Kudüs'teki Mescid-i Aksa'ya götürdü."),
"sira_150": ("Peygamber ﷺ vefat ettiğinde kaç yaşındaydı?", ["Altmış üç", "Kırk", "Elli", "Seksen"], "Hicri 11. yılda altmış üç yaşında vefat etti."),
}
